/**
 * Unit tests for CategoryPlot.removeDomainMarker.
 */
public class CategoryPlot_removeDomainMarker_TriageGen2Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private maps of CategoryPlot using reflection.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkers(Map<Integer, ArrayList<Marker>> map, int index, ArrayList<Marker> list) throws Exception {
        Field field = CategoryPlot.class.getDeclaredField(map == null ? "foregroundDomainMarkers" : 
                (map.hashCode() == 0 ? "backgroundDomainMarkers" : "foregroundDomainMarkers")); 
        // Note: The reflection logic above is a bit abstract due to the provided snippet's structure.
        // In a real scenario, we target the specific field name.
    }

    /**
     * Since the fields foregroundDomainMarkers and backgroundDomainMarkers are private, 
     * we use reflection to setup the test state.
     */
    private void setMarkersField(String fieldName, int index, ArrayList<Marker> markersList) throws Exception {
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        if (map == null) {
            map = new HashMap<>();
            field.set(plot, map);
        }
        map.put(index, markersList);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_MarkersNull() throws Exception {
        // Test branch: layer == FOREGROUND and markers == null
        setMarkersField("foregroundDomainMarkers", 0, null);

        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Should return true when markers list is null", result);
    }

    @Test
    public void testRemoveDomainMarker_Background_MarkersNull() throws Exception {
        // Test branch: layer == BACKGROUND and markers == null
        setMarkersField("backgroundDomainMarkers", 0, null);

        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Should return true when markers list is null", result);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_RemoveSuccess_NotifyTrue() throws Exception {
        // Test branch: layer == FOREGROUND, marker found, notify == true
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        setMarkersField("foregroundDomainMarkers", 1, list);

        boolean result = plot.removeDomainMarker(1, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Should return true when marker is removed", result);
        assertTrue("List should be empty", list.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_RemoveSuccess_NotifyFalse() throws Exception {
        // Test branch: layer == FOREGROUND, marker found, notify == false
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        setMarkersField("foregroundDomainMarkers", 1, list);

        boolean result = plot.removeDomainMarker(1, mockMarker, Layer.FOREGROUND, false);

        assertTrue("Should return true when marker is removed", result);
        assertTrue("List should be empty", list.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_RemoveFailure() throws Exception {
        // Test branch: layer == FOREGROUND, marker NOT found
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class));
        setMarkersField("foregroundDomainMarkers", 1, list);

        boolean result = plot.removeDomainMarker(1, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker is not in list", result);
        assertEquals("List size should remain 1", 1, list.size());
    }

    @Test
    public void testRemoveDomainMarker_Background_RemoveSuccess() throws Exception {
        // Test branch: layer == BACKGROUND, marker found
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        setMarkersField("backgroundDomainMarkers", 5, list);

        boolean result = plot.removeDomainMarker(5, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Should return true when marker is removed from background", result);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Background_RemoveFailure() throws Exception {
        // Test branch: layer == BACKGROUND, marker NOT found
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class));
        setMarkersField("backgroundDomainMarkers", 5, list);

        boolean result = plot.removeDomainMarker(5, mockMarker, Layer.BACKGROUND, true);

        assertFalse("Should return false when marker is not in background list", result);
    }
}
